// Obtenemos el state completo desde el Webhook
const state = $('Webhook Cancelar').first().json.query.state;

// Lo separamos usando el delimitador "|"
const [timestamp, uuid] = state.split('|');

// Retornamos ambos valores por separado
return {
  json: {
    timestamp,
    uuid
  }
};

const reservasExistentes = $("Leer reservas para recordatorio").all().map(item => item.json);

// Obtenemos la fecha de hoy y calculamos la de mañana
const hoy = new Date();
const manana = new Date(hoy);
manana.setDate(hoy.getDate() + 1);

// Formateamos la fecha de mañana en YYYY-MM-DD
const yyyy = manana.getFullYear();
const mm = String(manana.getMonth() + 1).padStart(2, '0');
const dd = String(manana.getDate()).padStart(2, '0');
const fechaManana = `${yyyy}-${mm}-${dd}`;

// Filtramos las reservas cuya Fecha coincida con mañana
const reservasManana = reservasExistentes.filter(r => r.Fecha === fechaManana);

if (reservasManana.length === 0) {
  // Caso sin reservas: retornamos un item con recordatorio = false
  return [
    {
      json: { recordatorio: false}
    }
  ];
}

// Caso con reservas: retornamos cada reserva como item independiente, con recordatorio = true
return reservasManana.map(r => ({
  json: { ...r, recordatorio: true }
}));

// --- Función de sanitización ---
function sanitizeInput(str) {
  if (!str) return "";
  return String(str)
    .trim()
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

// --- Regex para validar correo ---
function validarCorreo(email) {
  const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return regex.test(email);
}

// Obtenemos todas las reservas de mañana
const reservas = $("Reservas para mañana").all();

const items = reservas
  .map(item => {
    const sala = sanitizeInput(item.json.Sala);
    const fecha = sanitizeInput(item.json.Fecha);
    const inicio = sanitizeInput(item.json.HoraInicio);
    const fin = sanitizeInput(item.json.HoraFin);
    const titulo = sanitizeInput(item.json.Titulo);
    const descripcion = item.json.Descripcion ? sanitizeInput(item.json.Descripcion) : "Sin descripción";
    const correosRaw = item.json["Correos participantes"] || "";
    const linkCalendar = sanitizeInput(item.json["Link_Calendar"]);

    // Procesamos los correos: split, trim, sanitize y validación regex
    const correosValidos = correosRaw
      .split(",")
      .map(c => sanitizeInput(c.trim()))
      .filter(c => validarCorreo(c));

    // Si no hay correos válidos, descartamos este item
    if (correosValidos.length === 0) {
      return null;
    }

    // HTML recordatorio
    const htmlRecordatorio = `
    <!DOCTYPE html>
    <html lang="es">
      <head>
        <meta charset="UTF-8" />
        <title>Recordatorio de reunión</title>
        <style>
          body { font-family: Arial, sans-serif; background:#f6f7fb; color:#222; }
