          th, td { border:1px solid #dfe3e8; padding:8px; text-align:left; }
          th { background:#f1f3f7; }
        </style>
      </head>
      <body>
        <div class="container">
          <div class="card">
            <h1 class="title">Recordatorio de reunión</h1>
            <p class="text">
              Estimados participantes, les recordamos que mañana tienen una reunión programada con los siguientes detalles:
            </p>
            <table>
              <tr><th>Título</th><td>${titulo}</td></tr>
              <tr><th>Descripción</th><td>${descripcion}</td></tr>
              <tr><th>Sala</th><td>${sala}</td></tr>
              <tr><th>Fecha</th><td>${fecha}</td></tr>
              <tr><th>Hora Inicio</th><td>${inicio}</td></tr>
              <tr><th>Hora Fin</th><td>${fin}</td></tr>
            </table>
            <p class="text">
              Pueden revisar el evento en su calendario aquí: <a href="${linkCalendar}">Ver en Google Calendar</a>
            </p>
          </div>
        </div>
      </body>
    </html>
    `;

    return {
      json: {
        correos: correosValidos.join(","), // string limpio para Gmail
        subject: `Recordatorio de reunión - ${titulo}`,
        html: htmlRecordatorio,
        text: `Recordatorio: mañana tiene reunión en la sala ${sala}, el día ${fecha} de ${inicio} a ${fin}.`
      }
    };
  })
  .filter(item => item !== null); // quitamos los descartados

return items;

