const fecha = $('Crear ID reserva y sanitizar campos').first().json.fecha;
const inicio = $('Crear ID reserva y sanitizar campos').first().json.inicio;
const termino = $('Crear ID reserva y sanitizar campos').first().json.termino;
const area = $('Crear ID reserva y sanitizar campos').first().json.area;
