// --- Entradas ---
const correo = $('Extraer solicitud de reserva').first().json.Correo;
const nombre = $('Extraer solicitud de reserva').first().json.Nombre;
const titulo = $('Extraer solicitud de reserva').first().json.Titulo;
const descripcion = $('Extraer solicitud de reserva').first().json.Descripcion;
const fecha = $('Extraer solicitud de reserva').first().json.Fecha;
const inicio = $('Extraer solicitud de reserva').first().json['Hora inicio'];
const termino = $('Extraer solicitud de reserva').first().json['Hora termino'];
const area = $('Extraer solicitud de reserva').first().json.Area;
const NumeroParticipantes = $('Extraer solicitud de reserva').first().json.Participantes;
const sala = $('Extraer solicitud de reserva').first().json.Sala;
const correos = $('Extraer solicitud de reserva').first().json['Correos Participantes'];

// --- Funciones auxiliares ---
function sanitize(value) {
  if (value === undefined || value === null) return null;

  if (typeof value === 'string') {
    // Limpiar espacios y eliminar caracteres < >
    const clean = value.trim().replace(/[<>]/g, "");
    return clean.length > 0 ? clean : null;
  }

  if (typeof value === 'number') {
    return isNaN(value) ? null : value;
  }

  return null;
}

function validarCorreo(email) {
  if (!email) return false;
  const regex = /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/;
  return regex.test(email.trim());
}

function normalizeHour(horaStr) {
  if (!horaStr) return null;
  const [h, m] = horaStr.split(':');
  const hh = h.padStart(2, '0'); // asegura dos dígitos
  return `${hh}:${m}`;
}

function toCalendarDate(fechaStr, horaStr) {
  if (!fechaStr || !horaStr) return null;
  const horaNormalizada = normalizeHour(horaStr);
  const date = new Date(`${fechaStr}T${horaNormalizada}:00`);
  if (isNaN(date.getTime())) return null;
  return date.toISOString().slice(0,16)+":00"; // formato YYYY-MM-DDTHH:MM:00
}

// --- Sanitizar campos ---
const correoSanitizado = sanitize(correo);
const correoLimpio = validarCorreo(correoSanitizado) ? correoSanitizado : null;

const nombreLimpio = sanitize(nombre);
const tituloLimpio = sanitize(titulo);
const descripcionLimpio = sanitize(descripcion);
const fechaLimpia = sanitize(fecha);
const inicioLimpio = sanitize(inicio);
const terminoLimpio = sanitize(termino);
const areaLimpia = sanitize(area);
const participantesLimpio = sanitize(NumeroParticipantes);
const salaLimpia = sanitize(sala);

// --- Correos participantes ---
let correosValidos = null;
if (correos && typeof correos === 'string') {
  let lista = [];
  try {
    // Intentar parsear como JSON (ej. ["correo1","correo2"])
    lista = JSON.parse(correos);
  } catch (e) {
    // Si no es JSON válido, fallback: split por coma
    lista = correos.split(',');
  }

  const filtrados = lista
    .map(c => sanitize(c))
    .filter(c => c && validarCorreo(c));

  if (filtrados.length > 0) {
    // Unir en formato que Gmail acepta: "correo1,correo2"
    correosValidos = filtrados.join(',');
  }
}

// --- Fechas para Google Calendar ---
const inicioCalendar = toCalendarDate(fechaLimpia, inicioLimpio);
const terminoCalendar = toCalendarDate(fechaLimpia, terminoLimpio);

// --- ID para Calendar ---
const calendarId = Date.now().toString(); // solo números

// --- Salida ---
return [
  {
    json: {
      correo: correoLimpio,
      nombre: nombreLimpio,
      titulo: tituloLimpio,
      descripcion: descripcionLimpio,
      fecha: fechaLimpia,
      inicio: inicioLimpio,
      termino: terminoLimpio,
      area: areaLimpia,
      participantes: participantesLimpio,
      sala: salaLimpia,
      correos_participantes: correosValidos,
      inicio_calendar: inicioCalendar,
      termino_calendar: terminoCalendar,
      calendar_id: calendarId
    }
  }
];

// Función para limpiar valores potencialmente peligrosos
function sanitize(value) {
  if (typeof value !== "string") return value;
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
