// Verificamos si existe algún objeto con propiedades dentro de json
const tieneContenido = items.length > 0 && items.some(item => {
  const payload = item && item.json ? item.json : {};
  return Object.keys(payload).length > 0;
});

// Marca temporal ISO
const timestamp = new Date().toISOString();

