const cierre   = $input.first().json['Hora cierre'];     // ej: "23:00"
const inicio   = $('Normalizar, sanitizar y validar reserva').first().json.hora_inicio; // ej: "09:00"
const termino  = $('Normalizar, sanitizar y validar reserva').first().json.hora_termino; // ej: "11:00"

// --- Función auxiliar: convierte "HH:MM" a minutos desde medianoche ---
function toMinutes(horaStr) {
  const [h, m] = horaStr.split(':').map(Number);
  return h * 60 + m;
}

// --- Convertimos todas las horas ---
const aperturaMin = toMinutes(apertura);
const cierreMin   = toMinutes(cierre);
const inicioMin   = toMinutes(inicio);
const terminoMin  = toMinutes(termino);

// --- Validación ---
let valido = true;
let mensaje = "Reserva dentro del rango permitido ✅";

if (inicioMin < aperturaMin) {
  valido = false;
  mensaje = `La hora de inicio (${inicio}) es anterior a la apertura (${apertura}).`;
} else if (terminoMin > cierreMin) {
  valido = false;
  mensaje = `La hora de término (${termino}) es posterior al cierre (${cierre}).`;
} else if (terminoMin <= inicioMin) {
  valido = false;
  mensaje = `La hora de término (${termino}) debe ser posterior a la hora de inicio (${inicio}).`;
}

// --- Salida ---
return [
  {
    json: {
      apertura,
      cierre,
      inicio,
      termino,
      valido,
      mensaje
    }
  }
];

// Tomamos el primer item de entrada
const entrada = $input.first().json;

// Array de reservas
const reservas = entrada.registros || [];

// Generamos un item por cada reserva, arreglando "Correos participantes"
return reservas.map(r => {
  let correosParticipantes = [];

  if (r["Correos participantes"]) {
    try {
      // Intentamos parsear como JSON
      correosParticipantes = JSON.parse(r["Correos participantes"]);
    } catch (e) {
      // Si no es JSON válido, lo tratamos como lista separada por comas
      correosParticipantes = r["Correos participantes"]
        .split(",")
        .map(c => c.trim())
        .filter(c => c.length > 0);
    }
  }

  return {
    json: {
      ...r,
      correos_participantes: correosParticipantes // array limpio
    }
  };
});

// Tomamos todos los items de entrada (cada reserva ya es un item)
const reservas = $input.all();

// Filtramos y generamos un item solo para las reservas con participantes
return reservas
  .filter(r => Array.isArray(r.json.correos_participantes) && r.json.correos_participantes.length > 0)
  .map(r => {
    const correosArray = r.json.correos_participantes;
    const campoGmail = correosArray.join(',');

    // Construimos el HTML del mensaje
    const htmlMensaje = `
      <html>
        <body>
          <p>Lo sentimos, debido a la eliminación de su sala, la reserva de <strong>${r.json.Fecha}</strong>, a las <strong>${r.json.HoraInicio}-${r.json.HoraFin}</strong>, será cancelada.</p>
        </body>
      </html>
    `;

    return {
      json: {
        ...r.json,
        campoGmail,   // string con todos los correos unidos por coma
        htmlMensaje   // HTML personalizado para el correo
      }
    };
  });

// Tomamos el array completo de reservas desde la entrada
const reservas = $input.all().map(item => item.json);

// Ordenamos en orden descendente por row_number
const ordenadas = reservas.sort((a, b) => b.row_number - a.row_number);

// Generamos un item por cada reserva, solo con el row_number
return ordenadas.map(r => ({
  json: {
    row_number: r.row_number
  }
}));

// Reservas existentes (misma sala y fecha)
const reservasRaw = $("Reservas que coinciden con sala/fecha").all();

// Horas de la nueva solicitud
const inicio = $('Normalizar, sanitizar y validar reserva').first().json.hora_inicio;
const termino = $('Normalizar, sanitizar y validar reserva').first().json.hora_termino;

// Función para convertir HH:MM a minutos
function toMinutes(hora) {
  const [hh, mm] = hora.split(":").map(Number);
  return hh * 60 + mm;
}

const inicioSolicitud = toMinutes(inicio);
const terminoSolicitud = toMinutes(termino);

// Filtrar reservas válidas (que tengan HoraInicio y HoraFin)
const reservas = reservasRaw
  .map(r => r.json)
  .filter(r => r.HoraInicio && r.HoraFin);

let conflictos = [];

reservas.forEach(r => {
  const inicioReserva = toMinutes(r.HoraInicio);
  const terminoReserva = toMinutes(r.HoraFin);

  // Se solapan si los rangos se cruzan, excluyendo casos adyacentes
  const seSolapan = inicioSolicitud < terminoReserva && terminoSolicitud > inicioReserva;

  if (seSolapan) {
    conflictos.push({
      row_number: r.row_number,
      sala: r.Sala,
      fecha: r.Fecha,
      hora_inicio: r.HoraInicio,
      hora_fin: r.HoraFin
    });
  }
});

// Resultado
return [
  {
    json: {
      solicitud: { inicio, termino },
      conflictos,
      hay_conflictos: conflictos.length > 0
    }
  }
];

